<script setup lang="ts">
import { artworkURL } from '../artwork'
import { ref, watch, nextTick } from 'vue'
import { useMusic } from '../stores/music'
import { useOverlay } from '../stores/overlay'
import { musicApi } from '../core'
import type { ExportData } from '../core'
import Icon from './Icon.vue'
const music=useMusic(),overlay=useOverlay(),name=ref(''),recovery=ref(''),recoveryInput=ref(''),nameInput=ref<HTMLInputElement>(),working=ref(false)
watch(()=>overlay.kind,async kind=>{if(kind==='create'){name.value='';await nextTick();nameInput.value?.focus()}if(kind!=='transfer')recovery.value=''})
async function create(){if(!name.value.trim())return;working.value=true;const p=await music.create(name.value,overlay.track?[overlay.track.id]:[]);if(p)overlay.close();working.value=false}
async function add(id:string){const p=music.playlists.find(p=>p.id===id);if(p&&overlay.track){const result=await music.add(p,overlay.track);if(result)overlay.close()}}
async function exportJSON(){await music.run(async()=>{const data=await musicApi.exportData();const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='betago-music-v1.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function importJSON(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await music.run(async()=>{if(file.size>2*1024*1024)throw new Error('备份文件不能超过 2 MiB');await music.importData(JSON.parse(await file.text()) as ExportData)});input.value=''}
async function recover(){working.value=true;await music.changeSession(()=>musicApi.recover(recoveryInput.value));working.value=false}
async function copy(){await music.run(async()=>{await navigator.clipboard.writeText(overlay.shareURL);music.notify('分享链接已复制')})}
</script>
<template><Teleport to="body"><div v-if="overlay.kind" class="modal-shade" @click.self="overlay.close()"><section class="dialog" :class="{'dialog-wide':overlay.kind==='transfer'}" role="dialog" aria-modal="true" :aria-label="{create:'新建歌单',add:'加入歌单',share:'分享音乐',transfer:'备份与恢复'}[overlay.kind]"><button class="icon-button dialog-close" aria-label="关闭" @click="overlay.close()"><Icon name="close"/></button>
 <form v-if="overlay.kind==='create'" @submit.prevent="create"><span class="eyebrow">A PLACE FOR YOUR FAVORITES</span><h2>给这份喜欢起个名字。</h2><label class="field-label" for="playlist-name">歌单名称</label><input id="playlist-name" ref="nameInput" v-model="name" maxlength="100" placeholder="例如：下班路上的歌" required/><p class="muted">歌单默认私有，你可以随时创建或撤销分享。</p><button class="primary full" :disabled="working">{{working?'保存中…':'创建歌单'}}</button></form>
 <template v-else-if="overlay.kind==='add'"><span class="eyebrow">SAVE TO YOUR COLLECTION</span><h2>加入歌单</h2><p class="muted">{{overlay.track?.title}}</p><div class="dialog-playlists"><button v-for="p in music.playlists" :key="p.id" @click="add(p.id)"><img :src="artworkURL(p.tracks[0]?.picture)" alt=""/><span><strong>{{p.name}}</strong><small>{{p.tracks.length}} 首歌曲</small></span><Icon name="plus"/></button></div><button class="subtle full" @click="overlay.create()"><Icon name="plus" :size="17"/> 新建歌单</button></template>
 <template v-else-if="overlay.kind==='share'"><span class="eyebrow">GOOD MUSIC IS MEANT TO BE SHARED</span><h2>分享这份音乐。</h2><p class="muted">持有链接的人可以查看和复制歌单。分享只读，可在「分享管理」随时撤销。</p><label class="field-label" for="share-link">分享链接</label><input id="share-link" :value="overlay.shareURL" readonly @click="($event.target as HTMLInputElement).select()"/><button class="primary full" @click="copy"><Icon name="share" :size="17"/> 复制链接</button></template>
 <template v-else><span class="eyebrow">TAKE YOUR MUSIC WITH YOU</span><h2>音乐，也能带走。</h2><p class="muted">访客空间由当前浏览器的会话识别。其他设备不会自动认出你；恢复码可以打开同一空间，JSON 备份会复制歌单和喜欢。</p><p v-if="music.identityMessage" class="muted">{{music.identityMessage}}</p><div v-if="music.userKind==='feishu'" class="notice">已连接飞书个人空间，身份由后端核实。</div><div v-else-if="music.feishuEnabled&&music.inFeishu" class="recovery-area"><h3>切换到飞书个人空间</h3><p class="muted">飞书空间与当前访客空间分别保存，不会自动合并。先导出 JSON 或保存下方恢复码，再切换；之后可将 JSON 导入飞书空间。</p><button v-if="!recovery" class="subtle" @click="music.run(async()=>recovery=await musicApi.recovery())">先生成访客恢复码</button><template v-else><code class="recovery-code">{{recovery}}</code><button class="primary" @click="music.connectFeishu()">我已保存恢复码，连接飞书</button></template></div><p v-else-if="music.inFeishu" class="muted">当前飞书网页身份尚未配置，访客功能可正常使用。</p><div class="transfer-options"><button @click="exportJSON"><Icon name="backup"/><strong>导出 JSON 备份</strong><small>歌单与喜欢，不含音频或密钥</small></button><label class="import-file"><Icon name="library"/><strong>导入 JSON 备份</strong><small>复制到当前空间</small><input type="file" aria-label="导入 JSON" accept="application/json,.json" @change="importJSON"/></label></div><div class="recovery-area"><h3>恢复到另一台设备</h3><p class="muted">恢复码相当于空间钥匙，请私密保存。清除浏览器数据后，仍可用它恢复；轮换后旧码立即失效。</p><button class="subtle" @click="music.run(async()=>recovery=await musicApi.recovery())">生成 / 轮换恢复码</button><code v-if="recovery" class="recovery-code" data-testid="recovery-code">{{recovery}}</code><form class="recover-form" @submit.prevent="recover"><input v-model="recoveryInput" aria-label="恢复码" type="password" autocomplete="off" placeholder="输入保存的恢复码" required/><button :disabled="working" class="primary">恢复空间</button></form></div></template>
 <p v-if="music.error" class="dialog-error" role="alert">{{music.error}}</p>
 </section></div></Teleport></template>
